#define TABLE_SIZE (1u << 21)
#define EMPTY_KEY 0xFFFFFFFFu

static unsigned hash_u32(unsigned x) {
    x ^= x >> 16;
    x *= 0x7feb352du;
    x ^= x >> 15;
    x *= 0x846ca68bu;
    x ^= x >> 16;
    return x;
}

static void clear_table(unsigned* table) {
    for (unsigned i = 0; i < TABLE_SIZE; ++i) table[i] = EMPTY_KEY;
}

static void insert_key(unsigned* table, unsigned x) {
    unsigned mask = TABLE_SIZE - 1u;
    unsigned i = hash_u32(x) & mask;
    while (table[i] != EMPTY_KEY && table[i] != x) i = (i + 1u) & mask;
    table[i] = x;
}

static bool contains_key(const unsigned* table, unsigned x) {
    unsigned mask = TABLE_SIZE - 1u;
    unsigned i = hash_u32(x) & mask;
    while (table[i] != EMPTY_KEY) {
        if (table[i] == x) return true;
        i = (i + 1u) & mask;
    }
    return false;
}

int findMaximumXOR(int* nums, int numsSize) {
    unsigned ans = 0;
    unsigned* table = (unsigned*)malloc((size_t)TABLE_SIZE * sizeof(unsigned));
    if (!table) return 0;

    for (int bit = 30; bit >= 0; --bit) {
        unsigned candidate = ans | (1u << bit);
        clear_table(table);
        for (int i = 0; i < numsSize; ++i) {
            insert_key(table, ((unsigned)nums[i]) & candidate);
        }

        bool possible = false;
        for (int i = 0; i < numsSize; ++i) {
            unsigned p = ((unsigned)nums[i]) & candidate;
            if (contains_key(table, p ^ candidate)) {
                possible = true;
                break;
            }
        }
        if (possible) ans = candidate;
    }

    free(table);
    return (int)ans;
}

