class Solution {
    static constexpr int TABLE_SIZE=1<<21, EMPTY=-1;
    static uint32_t h(uint32_t x){x^=x>>16;x*=0x7feb352dU;x^=x>>15;x*=0x846ca68bU;x^=x>>16;return x;}
public:
    int findMaximumXOR(vector<int>& nums){
        vector<int> t(TABLE_SIZE,EMPTY); int ans=0,mask=TABLE_SIZE-1;
        for(int bit=30;bit>=0;--bit){
            int cand=ans|(1<<bit); fill(t.begin(),t.end(),EMPTY);
            for(int x:nums){int p=x&cand,i=(int)(h((uint32_t)p)&(uint32_t)mask);while(t[i]!=EMPTY&&t[i]!=p)i=(i+1)&mask;t[i]=p;}
            bool ok=false;
            for(int x:nums){int p=x&cand,w=p^cand,i=(int)(h((uint32_t)w)&(uint32_t)mask);while(t[i]!=EMPTY&&t[i]!=w)i=(i+1)&mask;if(t[i]==w){ok=true;break;}}
            if(ok)ans=cand;
        }
        return ans;
    }
};

