class Solution {
    private static final int TABLE_SIZE = 1 << 21;
    private static final int EMPTY = -1;
    private static int hash(int x) {
        x ^= x >>> 16; x *= 0x7feb352d; x ^= x >>> 15; x *= 0x846ca68b; x ^= x >>> 16; return x;
    }
    private static void add(int[] t, int x) { int m=t.length-1, i=hash(x)&m; while(t[i]!=EMPTY&&t[i]!=x)i=(i+1)&m; t[i]=x; }
    private static boolean has(int[] t, int x) { int m=t.length-1, i=hash(x)&m; while(t[i]!=EMPTY){if(t[i]==x)return true;i=(i+1)&m;} return false; }
    public int findMaximumXOR(int[] nums) {
        int ans=0; int[] table=new int[TABLE_SIZE];
        for(int bit=30;bit>=0;--bit){
            int cand=ans|(1<<bit); Arrays.fill(table,EMPTY);
            for(int x:nums)add(table,x&cand);
            boolean ok=false; for(int x:nums){int p=x&cand;if(has(table,p^cand)){ok=true;break;}}
            if(ok)ans=cand;
        }
        return ans;
    }
}

